//! `ShellRunner` outbound adapter (the process boundary, P6.F2).
//!
//! OP2: a shell-runner **enum** implements the `CommandRunner` port; one
//! variant per supported shell, and the delegating `match` is generated by a
//! single `macro_rules!` (`delegate_run!`) so adding a shell is a one-token
//! change. `std::process::Command` is confined to this file (ARCH-03); every
//! failure is translated into the port's `RunError` variants — spawn failures
//! become `RunError::Spawn`, wait I/O failures the `RunError::Other`
//! catch-all, and a non-zero exit status `RunError::Waited` (ERR-04).
//!
//! **Exit-status surfacing (V-ERR-09 runner half, P6.F2):** after `wait()`, a
//! non-zero exit status maps to `RunError::Waited { code }`; a zero exit
//! returns `Ok(())`. The service's handling of that error is a separate P6.F3
//! concern.

use std::process::{Command as SystemCommand, Stdio};

use crate::domain::queue::QueueEntry;
use crate::domain::shell::Shell;
use crate::ports::command_runner::{CommandRunner, RunError};

/// A shell the queue runner can spawn (the outbound half of the domain
/// [`Shell`]).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ShellRunner {
    /// Spawn `fish -c <entry>`.
    Fish,
    /// Spawn `bash -c <entry>`.
    Bash,
    /// Spawn `sh -c <entry>`.
    Sh,
}

/// The documented domain → outbound mapping (one-to-one on variant names).
impl From<Shell> for ShellRunner {
    fn from(shell: Shell) -> Self {
        match shell {
            Shell::Fish => ShellRunner::Fish,
            Shell::Bash => ShellRunner::Bash,
            Shell::Sh => ShellRunner::Sh,
        }
    }
}

/// Run `program -c <entry>` with inherited stdio, translating the outcome into
/// [`RunError`]. A non-zero exit status surfaces as `RunError::Waited`
/// (V-ERR-09 runner half); a zero exit (or a signal-terminated process, which
/// carries no exit code) returns `Ok(())`.
fn run_with(program: &str, entry: &QueueEntry) -> Result<(), RunError> {
    let mut child = SystemCommand::new(program)
        .arg("-c")
        .arg(entry.as_str())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(RunError::Spawn)?;

    let status = child.wait().map_err(RunError::Other)?;
    match status.code() {
        Some(code) if code != 0 => Err(RunError::Waited { code }),
        _ => Ok(()),
    }
}

/// Generate the `CommandRunner` implementation for `ShellRunner` as one
/// `match` that selects the domain [`Shell`], delegating to `run_with` with
/// that shell's `program()` (OP2 owner preference 2 — the delegating `match`
/// is macro-generated, not hand-written; the program name stays sourced from
/// the domain `Shell`).
macro_rules! delegate_run {
    ($($variant:ident),* $(,)?) => {
        impl CommandRunner for ShellRunner {
            fn run(&self, entry: &QueueEntry) -> Result<(), RunError> {
                let shell = match self {
                    $(ShellRunner::$variant => Shell::$variant),*
                };
                run_with(shell.program(), entry)
            }
        }
    };
}

delegate_run!(Fish, Bash, Sh);

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::shell::Shell;

    fn entry(line: &str) -> QueueEntry {
        QueueEntry::new(line).unwrap()
    }

    /// `sh -c true` exits 0 → `Ok(())` (the established outbound-adapter
    /// pattern; `sh` is present in this container, `fish` is not).
    #[test]
    fn sh_zero_exit_is_ok() {
        let runner = ShellRunner::Sh;
        assert!(runner.run(&entry("true")).is_ok());
    }

    /// `sh -c 'exit 3'` exits 3 → `RunError::Waited { code: 3 }`.
    #[test]
    fn sh_non_zero_exit_surfaces_waited() {
        let runner = ShellRunner::Sh;
        let err = runner.run(&entry("exit 3")).unwrap_err();
        assert!(matches!(err, RunError::Waited { code: 3 }));
    }

    /// Spawn failure maps to `RunError::Spawn`. An impossible binary name makes
    /// `spawn` fail deterministically whether or not the target shell is on the
    /// testing machine's `PATH` (the `dev` toolchain actually ships `fish`), so
    /// the `RunError::Spawn` translation is verified either way (assert the
    /// variant, not the message).
    #[test]
    fn spawn_failure_maps_to_spawn_error() {
        let entry = entry("true");
        let err = run_with("encode-queue-definitely-missing-binary-for-tests", &entry).unwrap_err();
        assert!(matches!(err, RunError::Spawn(_)));
    }

    /// `From<Shell>` maps every variant onto its namesake.
    #[test]
    fn from_shell_maps_every_variant() {
        assert_eq!(ShellRunner::from(Shell::Fish), ShellRunner::Fish);
        assert_eq!(ShellRunner::from(Shell::Bash), ShellRunner::Bash);
        assert_eq!(ShellRunner::from(Shell::Sh), ShellRunner::Sh);
    }
}
